scwin.clickBzProcsNo = "";
scwin.vScrenID = "ULDBNS30100.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명       : 일자 조회
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 설명       : 조회
 ***********************************************/
scwin.fn_Search = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    if (vsTabSel == "1" || vsTabSel == "2" || vsTabSel == "3" || vsTabSel == "4" || vsTabSel == "5") {
        scwin.fn_search_one();
    } else {
        scwin.fn_search_two();
    }
};



/********************************************** 
 * 설명       : 신규상장,추가상장,중도상환,스트립신규,스트립추가 및 재결합 탭에서 조회버튼 클릭시 조회
 ***********************************************/
scwin.fn_search_one = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var vsInOut = "";
    var vsSql = "";
    var voDtsList = null;
    var voGridList = null;

    // 신규상장
    if (vsTabSel == "1") {
        vsInOut = "BNS_TRESKY_BND_CLST_LIST1";
        vsSql = "lds.stf.bnstresky_bnd_cls.select.list1";
        voDtsList = dts_List1;
        voGridList = grd_List1;
        // 추가상장

    } else if (vsTabSel == "2") {
        vsInOut = "BNS_TRESKY_BND_CLST_LIST2";
        vsSql = "lds.stf.bnstresky_bnd_cls.select.list2";
        voDtsList = dts_List2;
        voGridList = grd_List2;
        // 중도상환

    } else if (vsTabSel == "3") {
        vsInOut = "BNS_TRESKY_BND_CLST_LIST3";
        vsSql = "lds.stf.bnstresky_bnd_cls.select.list3";
        voDtsList = dts_List3;
        voGridList = grd_List3;
        // 스트립신규

    } else if (vsTabSel == "4") {
        vsInOut = "BNS_TRESKY_BND_CLST_LIST4";
        vsSql = "lds.stf.bnstresky_bnd_cls.select.list4";
        voDtsList = dts_List4;
        voGridList = grd_List4;
        // 스트립추가 및 재결합

    } else if (vsTabSel == "5") {
        vsInOut = "BNS_TRESKY_BND_CLST_LIST5";
        vsSql = "lds.stf.bnstresky_bnd_cls.select.list5";
        voDtsList = dts_List5;
        voGridList = grd_List5;
    }
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + vsInOut;
    url += "&queryId=" + vsSql;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STD_DD=" + $c.stf.getObjectValue(edt_SDate);
    voDtsList.DataID = encodeURI(url);
    voDtsList.Reset();
    $c.cm.ShowWin(voGridList);
};


/********************************************** 
 * 설명       : 추가상장 및 스트립신규, 추가상장 및 스트립추가/재결합 탭에서 조회버튼 클릭 시 조회
 ***********************************************/
scwin.fn_search_two = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var vsInOut1 = "";
    var vsSql1 = "";
    var voDtsList1 = null;
    var voGridList1 = null;
    var vsInOut2 = "";
    var vsSql2 = "";
    var voDtsList2 = null;
    var voGridList2 = null;
    if (vsTabSel == "6") {
        vsInOut1 = "BNS_TRESKY_BND_CLST_LIST61";
        vsSql1 = "lds.stf.bnstresky_bnd_cls.select.list61";
        voDtsList1 = dts_List61;
        voGridList1 = grd_List61;
        vsInOut2 = "BNS_TRESKY_BND_CLST_LIST62";
        vsSql2 = "lds.stf.bnstresky_bnd_cls.select.list62";
        voDtsList2 = dts_List62;
        voGridList2 = grd_List62;
        // 추가상장 및 스트립추가/재결합

    } else if (vsTabSel == "7") {
        vsInOut1 = "BNS_TRESKY_BND_CLST_LIST71";
        vsSql1 = "lds.stf.bnstresky_bnd_cls.select.list71";
        voDtsList1 = dts_List71;
        voGridList1 = grd_List71;
        vsInOut2 = "BNS_TRESKY_BND_CLST_LIST72";
        vsSql2 = "lds.stf.bnstresky_bnd_cls.select.list72";
        voDtsList2 = dts_List72;
        voGridList2 = grd_List72;
    }
    var url1 = "/listingCommon.do?method=listGeneralForDynamicName";
    url1 += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url1 += "&outputMessageId=" + vsInOut1;
    url1 += "&queryId=" + vsSql1;
    url1 += "&SCREN_ID=" + scwin.vScrenID;
    url1 += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url1 += "&{P}V_STD_DD=" + $c.stf.getObjectValue(edt_SDate);
    voDtsList1.DataID = encodeURI(url1);
    voDtsList1.Reset();
    $c.cm.ShowWin(voGridList1);
    var url2 = "/listingCommon.do?method=listGeneralForDynamicName";
    url2 += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url2 += "&outputMessageId=" + vsInOut2;
    url2 += "&queryId=" + vsSql2;
    url2 += "&SCREN_ID=" + scwin.vScrenID;
    url2 += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url2 += "&{P}V_STD_DD=" + $c.stf.getObjectValue(edt_SDate);
    voDtsList2.DataID = encodeURI(url2);
    voDtsList2.Reset();
    $c.cm.ShowWin(voGridList2);
};



/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var voDtsList = null;
    var voGridList = null;
    var excelSheet = '';

    // 신규상장
    if (vsTabSel == "1") {
        excelSheet = '신규상장';
        voDtsList = dts_List1;
        voGridList = grd_List1;
        // 추가상장

    } else if (vsTabSel == "2") {
        excelSheet = '추가상장';
        voDtsList = dts_List2;
        voGridList = grd_List2;
        // 중도상환

    } else if (vsTabSel == "3") {
        excelSheet = '중도상환';
        voDtsList = dts_List3;
        voGridList = grd_List3;
        // 스트립신규

    } else if (vsTabSel == "4") {
        excelSheet = '스트립신규';
        voDtsList = dts_List4;
        voGridList = grd_List4;
        // 스트립추가 및 재결합

    } else if (vsTabSel == "5") {
        excelSheet = '스트립추가 및 재결합';
        voDtsList = dts_List5;
        voGridList = grd_List5;
        // 추가상장 및 스트립 신규

    } else if (vsTabSel == "6") {
        excelSheet = '추가상장 및 스트립 신규';
        voDtsList = dts_List61;
        voGridList = grd_List61;
        // 추가상장 및 스트립추가/재결합

    } else if (vsTabSel == "7") {
        excelSheet = '추가상장 및 스트립추가/재결합';
        voDtsList = dts_List71;
        voGridList = grd_List71;
    }
    if (voDtsList.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_국고채마감조회.xls";
        voGridList.GridToExcel(excelSheet, "", 8);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};




/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown67 = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var voDtsList = null;
    var voGridList = null;
    var excelSheet = '';

    // 추가상장 및 스트립 신규
    if (vsTabSel == "6") {
        excelSheet = '추가상장 및 스트립 신규';
        voDtsList = dts_List62;
        voGridList = grd_List62;
        // 추가상장 및 스트립추가/재결합

    } else if (vsTabSel == "7") {
        excelSheet = '추가상장 및 스트립추가/재결합';
        voDtsList = dts_List72;
        voGridList = grd_List72;
    }
    if (voDtsList.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '국고채마감조회';
        voGridList.GridToExcel(excelSheet, "", 8);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Search > onclick
     * 설명      : 조회버튼 클릭
     ***********************************************/
    scwin.fn_Search();
};
scwin.btn_SDate_onclick = function() {
    /********************************************** 
     * 함수명   : btn_SDate > onclick
     * 설명      : 신청일기간 시작일자 달력클릭
     ***********************************************/
    popUpCalendar2(edt_SDate);
};
scwin.btn_Excel_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Excel > onclick
     * 설명      : 엑셀버튼 클릭
     ***********************************************/
    scwin.fn_ExcelDown();
};
scwin.btn_Excel61_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Excel > onclick
     * 설명      : 엑셀버튼 클릭
